import{_ as c,C as i,o as n,c as l,ak as o,E as a,j as d,a as r}from"./chunks/framework.DxrHb2fb.js";const f=JSON.parse('{"title":"Badge 徽标","description":"","frontmatter":{},"headers":[],"relativePath":"components/badge.md","filePath":"components/badge.md","lastUpdated":1790174783000}'),h={name:"components/badge.md"};function s(b,t,u,p,g,m){const e=i("XhDemo");return n(),l("div",null,[t[0]||(t[0]=o('<h1 id="badge-徽标" tabindex="-1">Badge 徽标 <a class="header-anchor" href="#badge-徽标" aria-label="Permalink to &quot;Badge 徽标&quot;">​</a></h1><p>提示某个对象有需要注意的变化：未读数量、当前状态、是否为新。徽标表达“发生了什么”，不表达“这是什么”；后者由<a href="./tag">标签</a>承担。</p><div class="xh-resource-links"><a href="https://github.com/XiHanFun/XiHan.UI/tree/dev/ui/packages/engine/headless/src/badge" target="_blank" rel="noreferrer">Headless</a><a href="https://github.com/XiHanFun/XiHan.UI/blob/dev/ui/packages/design/styles/css/badge.css" target="_blank" rel="noreferrer">Styles</a><a href="https://github.com/XiHanFun/XiHan.UI/tree/dev/ui/packages/adapters/vue/src/components/badge" target="_blank" rel="noreferrer">Vue</a><a href="https://github.com/XiHanFun/XiHan.UI/tree/dev/ui/packages/adapters/react/src/components/badge" target="_blank" rel="noreferrer">React</a><a href="https://github.com/XiHanFun/XiHan.UI/blob/dev/ui/packages/adapters/web-components/src/elements/badge.ts" target="_blank" rel="noreferrer">Web Components</a></div><h2 id="用法" tabindex="-1">用法 <a class="header-anchor" href="#用法" aria-label="Permalink to &quot;用法&quot;">​</a></h2><p>被标记的元素写进默认插槽，角标自行贴到它的角上；计数、上限截断与 0 值收起都由角标计算</p>',5)),a(e,{src:"badge/01-basic"}),t[1]||(t[1]=o('<h2 id="组件结构" tabindex="-1">组件结构 <a class="header-anchor" href="#组件结构" aria-label="Permalink to &quot;组件结构&quot;">​</a></h2><p>加粗的是必需部件。</p><p><code>data-scope=&quot;badge&quot;</code>：<strong><code>root</code></strong> · <strong><code>indicator</code></strong></p><h2 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例&quot;">​</a></h2><h3 id="圆点与落点" tabindex="-1">圆点与落点 <a class="header-anchor" href="#圆点与落点" aria-label="Permalink to &quot;圆点与落点&quot;">​</a></h3><p>dot 只表示有而不表示数量；placement 决定挂在哪个角，rtl 下 end 自动落到左边</p>',6)),a(e,{src:"badge/02-dot"}),t[2]||(t[2]=d("h3",{id:"语气与尺寸",tabindex:"-1"},[r("语气与尺寸 "),d("a",{class:"header-anchor",href:"#语气与尺寸","aria-label":'Permalink to "语气与尺寸"'},"​")],-1)),t[3]||(t[3]=d("p",null,"tone 决定使用哪族颜色：角标实际以未读红点与在线/离线点为主；size 改变圆点直径、两位数时的最小宽度与字号",-1)),a(e,{src:"badge/03-tone-size"}),t[4]||(t[4]=d("h3",{id:"自定义角标内容",tabindex:"-1"},[r("自定义角标内容 "),d("a",{class:"header-anchor",href:"#自定义角标内容","aria-label":'Permalink to "自定义角标内容"'},"​")],-1)),t[5]||(t[5]=d("p",null,"拆为 Root + Indicator 两件：角标内可自行排版，插槽可得到计算好的计数；不写内容才回落为数字，showZero 让 0 保留显示",-1)),a(e,{src:"badge/04-custom-indicator"}),t[6]||(t[6]=o('<h2 id="设计指引" tabindex="-1">设计指引 <a class="header-anchor" href="#设计指引" aria-label="Permalink to &quot;设计指引&quot;">​</a></h2><h3 id="何时使用" tabindex="-1">何时使用 <a class="header-anchor" href="#何时使用" aria-label="Permalink to &quot;何时使用&quot;">​</a></h3><ul><li>计数角标：未读消息、购物车件数、待办条数。</li><li>小圆点：只表示有新内容，不表示数量。</li><li>状态提示：在线 / 离线、进行中、新。</li><li>附着在按钮、头像、标签页、菜单项上，报告该对象的状态。</li></ul><h3 id="何时不用" tabindex="-1">何时不用 <a class="header-anchor" href="#何时不用" aria-label="Permalink to &quot;何时不用&quot;">​</a></h3><ul><li>表达分类、技能、筛选条件等实体身份时，使用<a href="./tag">标签</a>，它可以被移除。</li><li>用户需要点击它进行筛选或删除时，徽标不接受交互，应使用标签。</li><li>表达进度时，使用<a href="./progress">进度条</a>。</li><li>可开关的选项使用<a href="./toggle">切换按钮</a>。</li></ul><h3 id="特性" tabindex="-1">特性 <a class="header-anchor" href="#特性" aria-label="Permalink to &quot;特性&quot;">​</a></h3><ul><li>语气与尺寸两轴与其他组件同源；角标只有一种形态，没有形态轴。</li><li>默认使用 neutral；未读、错误等强提醒显式使用 danger。</li><li><code>placement</code> 决定挂在哪个角，四角可选，跟随文字方向。</li><li><code>count</code> 输出数字，超过 <code>max</code>（默认 99）时显示为“99+”。</li><li>计数为 0 时整个收起，需要显示 0 时开启 <code>showZero</code>。</li><li><code>dot</code> 收成一个圆点，只表示存在，不表示数量。</li><li>计数盒三档最小尺寸为 14 / 28 / 32px，角标只探出宿主四分之一，保持与宿主的视觉连接；sm 是贴在图标按钮角上的小号，字仍是 12px。</li><li><code>label</code> 为读屏提供完整语句，避免只读出一个数字。</li></ul><h3 id="组合" tabindex="-1">组合 <a class="header-anchor" href="#组合" aria-label="Permalink to &quot;组合&quot;">​</a></h3><ul><li>挂在<a href="./avatar">头像</a>、<a href="./button">按钮</a>、<a href="./tabs">标签页</a>的标签上作为角标：被标记的对象直接写进默认插槽，定位与偏移由组件承担，不需要外层再提供定位上下文。</li></ul><h3 id="最佳实践" tabindex="-1">最佳实践 <a class="header-anchor" href="#最佳实践" aria-label="Permalink to &quot;最佳实践&quot;">​</a></h3><ul><li>角标必须给 <code>label</code>：读屏只读出一个数字时，用户无法判断它的含义。</li><li>状态不能只用颜色区分，文字必须说明。</li><li>数量变化的场景交给 <code>count</code> 计算，不自行拼接“99+”，避免上限口径不一致。</li></ul><h3 id="反模式" tabindex="-1">反模式 <a class="header-anchor" href="#反模式" aria-label="Permalink to &quot;反模式&quot;">​</a></h3><ul><li>将徽标用作分类标签：它不可交互、不可移除。</li><li>一屏内大量使用高饱和度徽标，会使提醒失去意义。</li><li>用徽标承载长句子。</li></ul><h2 id="api-参考" tabindex="-1">API 参考 <a class="header-anchor" href="#api-参考" aria-label="Permalink to &quot;API 参考&quot;">​</a></h2><h3 id="产物" tabindex="-1">产物 <a class="header-anchor" href="#产物" aria-label="Permalink to &quot;产物&quot;">​</a></h3><table tabindex="0"><thead><tr><th>层</th><th>值</th></tr></thead><tbody><tr><td>自定义元素</td><td><code>&lt;xh-badge&gt;</code></td></tr><tr><td>Vue 组件</td><td><code>XhBadge</code> <code>XhBadgeIndicator</code> <code>XhBadgeRoot</code></td></tr><tr><td>状态机</td><td>无，<code>connect</code> 直接由 props 算属性</td></tr><tr><td>皮肤</td><td><code>@xihan-ui/styles/badge.css</code></td></tr></tbody></table><h3 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h3><table tabindex="0"><thead><tr><th>属性</th><th>类型</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td><code>count</code></td><td><code>number</code></td><td></td><td>计数。提供后角标自行显示数字，超过 max 时显示为「max+」。 与 indicator 的默认插槽二选一：插槽有内容时以插槽为准。</td></tr><tr><td><code>dot</code></td><td><code>boolean</code></td><td></td><td>只显示圆点，不显示数字。提供后 count 只用于决定是否显示。</td></tr><tr><td><code>label</code></td><td><code>string</code></td><td></td><td>读屏朗读该角标的方式。 角标挂在按钮、头像上时只朗读数字无法表达含义，需要由宿主提供「3 条未读」这类完整语句。</td></tr><tr><td><code>max</code></td><td><code>number</code></td><td></td><td>计数上限，默认 99：超过时只显示 99+，避免角标变形。</td></tr><tr><td><code>placement</code></td><td><code>BadgePlacement</code></td><td></td><td>挂在哪个角，默认 top-end（右上角；rtl 下自动落到左上）。</td></tr><tr><td><code>showZero</code></td><td><code>boolean</code></td><td></td><td>计数为 0 时是否仍然显示，默认不显示：没有未读时不应出现角标。</td></tr><tr><td><code>size</code></td><td><code>Size</code></td><td></td><td>尺寸：sm / md / lg。影响圆点直径、两位数时的最小宽度与字号。</td></tr><tr><td><code>tone</code></td><td><code>Tone</code></td><td></td><td>语气：brand / neutral / success / warning / danger / info，决定使用哪族颜色，默认 neutral。 角标实际使用中主要为 danger（未读红点）与 success / neutral（在线 / 离线点）。</td></tr></tbody></table><h3 id="插槽" tabindex="-1">插槽 <a class="header-anchor" href="#插槽" aria-label="Permalink to &quot;插槽&quot;">​</a></h3><p>仅列出带载荷的插槽。</p><table tabindex="0"><thead><tr><th>Vue 组件</th><th>插槽</th><th>载荷</th><th>说明</th></tr></thead><tbody><tr><td><code>XhBadge</code></td><td><code>default</code></td><td>—</td><td></td></tr><tr><td><code>XhBadgeIndicator</code></td><td><code>default</code></td><td><code>{ text: string }</code></td><td></td></tr></tbody></table><h3 id="react-适配器-props" tabindex="-1">React 适配器 props <a class="header-anchor" href="#react-适配器-props" aria-label="Permalink to &quot;React 适配器 props&quot;">​</a></h3><p>只列各组件自己声明的那些：继承自 <code>ComponentPropsWithRef</code> 的 DOM 属性不在其中，根组件上与上面 Props 表同名的也不重复列。Vue 的对应物是上面的插槽表。</p><table tabindex="0"><thead><tr><th>React 组件</th><th>属性</th><th>类型</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td><code>XhBadgeIndicator</code></td><td><code>children</code></td><td><code>SlotChildren&lt;BadgeIndicatorSlotProps&gt;</code></td><td></td><td></td></tr></tbody></table><h3 id="connect-api" tabindex="-1">connect API <a class="header-anchor" href="#connect-api" aria-label="Permalink to &quot;connect API&quot;">​</a></h3><p><code>getXxxProps()</code> 返回对应部件的宿主属性。</p><table tabindex="0"><thead><tr><th>成员</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td><code>visible</code></td><td><code>boolean</code></td><td>当前是否应渲染：计数为 0 且未开启 showZero 时为假。</td></tr><tr><td><code>text</code></td><td><code>string</code></td><td>计算后的显示文本：超过 max 时显示为「99+」；dot 模式与无 count 时为空串。</td></tr><tr><td><code>getRootProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td>锚点：被标记的对象（按钮、头像、标签页）放置在其中。</td></tr><tr><td><code>getIndicatorProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td>角标本身，绝对定位在 root 的某个角。</td></tr></tbody></table><h2 id="无障碍" tabindex="-1">无障碍 <a class="header-anchor" href="#无障碍" aria-label="Permalink to &quot;无障碍&quot;">​</a></h2><h3 id="键盘" tabindex="-1">键盘 <a class="header-anchor" href="#键盘" aria-label="Permalink to &quot;键盘&quot;">​</a></h3><p>规格出处：<a href="https://www.w3.org/WAI/ARIA/apg/" target="_blank" rel="noreferrer">W3C APG</a></p><p>无键盘交互（不接收焦点，或焦点行为完全由原生元素提供）。</p><h3 id="aria" tabindex="-1">ARIA <a class="header-anchor" href="#aria" aria-label="Permalink to &quot;ARIA&quot;">​</a></h3><p>以下属性由 <code>connect</code> 生成。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>indicator</code></td><td><code>aria-label</code></td><td>props.label</td></tr><tr><td><code>indicator</code></td><td><code>role</code></td><td>&#39;status&#39; | undefined</td></tr></tbody></table><h2 id="样式参考" tabindex="-1">样式参考 <a class="header-anchor" href="#样式参考" aria-label="Permalink to &quot;样式参考&quot;">​</a></h2><h3 id="皮肤" tabindex="-1">皮肤 <a class="header-anchor" href="#皮肤" aria-label="Permalink to &quot;皮肤&quot;">​</a></h3><p><code>@xihan-ui/styles/badge.css</code> 使用 <code>[data-scope=&quot;badge&quot;][data-part=&quot;root&quot;]</code> 部件选择器，位于 <code>xihan.components</code> 层。覆盖样式使用 <code>xihan.overrides</code>。</p><h3 id="数据属性" tabindex="-1">数据属性 <a class="header-anchor" href="#数据属性" aria-label="Permalink to &quot;数据属性&quot;">​</a></h3><p>由 <code>connect</code> 生成；条件不成立时不输出无值属性。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>root</code></td><td><code>data-placement</code></td><td>props.placement</td></tr><tr><td><code>indicator</code></td><td><code>data-dot</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>indicator</code></td><td><code>data-placement</code></td><td>props.placement</td></tr><tr><td><code>indicator</code></td><td><code>data-size</code></td><td>props.size</td></tr><tr><td><code>indicator</code></td><td><code>data-tone</code></td><td>props.tone</td></tr></tbody></table><h3 id="css-变量" tabindex="-1">CSS 变量 <a class="header-anchor" href="#css-变量" aria-label="Permalink to &quot;CSS 变量&quot;">​</a></h3><p>本组件公开覆盖槽由独立皮肤的实际消费位生成；默认来源、作用部件和状态均与 CSS 同源。</p><table tabindex="0"><thead><tr><th>变量</th><th>部件</th><th>CSS 属性</th><th>状态</th><th>默认来源</th><th>说明</th></tr></thead><tbody><tr><td><code>--xh-badge-bg</code></td><td><code>indicator</code></td><td><code>background</code></td><td><code>default</code></td><td><code>--xh-_tone</code></td><td>badge 的 indicator 部件 background 覆盖槽。</td></tr><tr><td><code>--xh-badge-dot-radius</code></td><td><code>indicator</code></td><td><code>border-radius</code></td><td><code>dot</code></td><td><code>--xh-shape-circle</code></td><td>badge 的 indicator 部件 border-radius 覆盖槽。</td></tr><tr><td><code>--xh-badge-dot-size</code></td><td><code>indicator</code></td><td><code>block-size</code><br><code>inline-size</code><br><code>min-inline-size</code></td><td><code>dot</code></td><td><code>--xh-_badge-dot</code></td><td>badge 的 indicator 部件 block-size、inline-size、min-inline-size 覆盖槽。</td></tr><tr><td><code>--xh-badge-fg</code></td><td><code>indicator</code></td><td><code>color</code></td><td><code>default</code></td><td><code>--xh-_tone-on</code></td><td>badge 的 indicator 部件 color 覆盖槽。</td></tr><tr><td><code>--xh-badge-font-size</code></td><td><code>indicator</code></td><td><code>font-size</code></td><td><code>default</code></td><td><code>--xh-_badge-font</code></td><td>badge 的 indicator 部件 font-size 覆盖槽。</td></tr><tr><td><code>--xh-badge-font-weight</code></td><td><code>indicator</code></td><td><code>font-weight</code></td><td><code>default</code></td><td><code>--xh-font-weight-medium</code></td><td>badge 的 indicator 部件 font-weight 覆盖槽。</td></tr><tr><td><code>--xh-badge-min-size</code></td><td><code>indicator</code></td><td><code>block-size</code><br><code>min-inline-size</code></td><td><code>default</code></td><td><code>--xh-_badge-min</code></td><td>badge 的 indicator 部件 block-size、min-inline-size 覆盖槽。</td></tr><tr><td><code>--xh-badge-px</code></td><td><code>indicator</code></td><td><code>padding-inline</code></td><td><code>default</code></td><td><code>--xh-_badge-px</code></td><td>badge 的 indicator 部件 padding-inline 覆盖槽。</td></tr><tr><td><code>--xh-badge-radius</code></td><td><code>indicator</code></td><td><code>border-radius</code></td><td><code>default</code></td><td><code>--xh-shape-pill</code></td><td>badge 的 indicator 部件 border-radius 覆盖槽。</td></tr><tr><td><code>--xh-badge-ring</code></td><td><code>indicator</code></td><td><code>border</code></td><td><code>default</code></td><td><code>--xh-bg-surface</code></td><td>badge 的 indicator 部件 border 覆盖槽。</td></tr></tbody></table><h3 id="动效" tabindex="-1">动效 <a class="header-anchor" href="#动效" aria-label="Permalink to &quot;动效&quot;">​</a></h3><p>本组件皮肤不含过渡与关键帧，也没有脚本驱动的动效：状态一变，外观立即到位。</p><h3 id="rtl" tabindex="-1">RTL <a class="header-anchor" href="#rtl" aria-label="Permalink to &quot;RTL&quot;">​</a></h3><p>皮肤用逻辑属性排布（<code>inline-start</code> 一族），<code>dir=&quot;rtl&quot;</code> 下自动镜像；另有按 <code>dir</code> 分支的规则。</p>',47))])}const q=c(h,[["render",s]]);export{f as __pageData,q as default};
